<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import type {EChartsOption} from 'echarts';
import {useEmergencyStore} from '../../../store/useEmergencyStore';import {useRealtimeStore} from '../../../store/useRealtimeStore';
import {emergencyPhaseLabels,type EmergencyResult} from '../../../types/emergency';import {simulationApi} from '../../../api/realtime';
import ChartCanvas from '../../Operation/components/ChartCanvas.vue';
const e=useEmergencyStore(),rt=useRealtimeStore();const emit=defineEmits<{close:[]}>();let timer:ReturnType<typeof setInterval>|undefined;
const local=ref('');const selected=computed(()=>e.availablePlans.find(p=>p.plan_code===e.selectedPlan));
const stale=computed(()=>{const c=e.comparison,f=rt.state?.flood;if(!c||!f)return false;return c.stale||c.scenario_id!==f.scenarioId||f.elapsedSimulationSeconds-c.baseline_simulation_time>30||Math.abs(f.rainfall-c.rainfall)>5||Math.abs(f.waterLevel-c.water_level)>.5;});
const rows=computed(()=>e.comparison?[e.comparison.baseline,...e.comparison.results]:[]);
function chart(key:'water_level'|'risk_score'):EChartsOption{return {animation:false,color:['#8293a4','#5ec8dc','#80d8a9','#e3bc67'],tooltip:{trigger:'axis'},legend:{top:0,textStyle:{color:'#c4d3df'}},grid:{left:55,right:20,top:40,bottom:36},xAxis:{type:'value',name:'min',min:0,max:30,axisLabel:{color:'#9cb4c8'},nameTextStyle:{color:'#9cb4c8'},splitLine:{lineStyle:{color:'#254155'}}},yAxis:{type:'value',name:key==='water_level'?'水位 cm':'规则风险 / 100',axisLabel:{color:'#9cb4c8'},nameTextStyle:{color:'#9cb4c8'},splitLine:{lineStyle:{color:'#254155'}}},series:rows.value.map((r,i)=>({name:r.plan_code==='BASELINE'?'维持当前状态':r.plan_code,type:'line',symbol:'none',lineStyle:{type:i===0?'dashed':'solid',width:2},data:r.timeline.map(p=>[p.minute,p[key]])}))};}
const water=computed(()=>chart('water_level')),risk=computed(()=>chart('risk_score'));
const response=(v:number|null)=>v===null?'>30 min':`${v.toFixed(1)} min`;
function result(code:string):EmergencyResult|undefined{return e.comparison?.results.find(p=>p.plan_code===code);}
async function toggleClock(){try{const s=await (rt.state?.running?simulationApi.stop():simulationApi.start());rt.applyRealtimeState(s);}catch{local.value='仿真时钟控制失败';}}
async function execute(){if(window.confirm('当前操作仅作用于软件仿真环境，不控制真实设备。'))await e.execute();}
onMounted(()=>{void e.plans();timer=setInterval(()=>void e.plans(),5000);});onBeforeUnmount(()=>{clearInterval(timer);e.previewTargets=[];});
</script>
<template><section class="panel emergency-panel" data-testid="emergency-panel"><header><div><span class="eyebrow">COUNTERFACTUAL SIMULATION</span><h3>应急方案推演 <small>{{e.execution?emergencyPhaseLabels[e.execution.phase]:e.selectedPlan?'已选择方案':e.comparison?'比较已生成':'等待比较'}}</small></h3></div><button @click="emit('close')">收起推演</button></header>
<p>软件反事实推演 · 简化模型辅助人工比较，不自动决定方案。资源消耗为指数，不是费用。</p>
<p class="emergency-assumption">{{rt.state?.flood?.rainfallRecession?'当前演示：极端暴雨持续到第 30 分钟，第 30–35 分钟回落到 20 mm/h；所有方案共用此计划。':'当前工况：持续极端暴雨可能超过全部泵的排水能力，措施可减缓增长，不保证水位下降。'}} 封控降低人员暴露，保留水量和现有车辆。</p>
<div class="emergency-actions"><button data-testid="emergency-clock" @click="toggleClock">{{rt.state?.running?'暂停仿真便于比较':'继续仿真'}}</button><button class="flood-primary" data-testid="emergency-compare" :disabled="e.loading||!e.availablePlans.some(p=>p.available)" @click="e.compare">{{e.loading?'正在处理…':'从当前状态推演 30 分钟'}}</button><span>10× 时 30 仿真秒仅约 3 秒，建议暂停后比较及确认。</span></div>
<p v-if="e.loading" role="status">正在从当前状态进行 30 分钟反事实推演或提交操作，请稍候…</p><p v-if="e.error||local" role="alert">{{e.error||local}}</p><p v-if="stale" class="emergency-stale" data-testid="emergency-stale">当前状态已变化，建议重新推演。旧结果仅供查看。</p>
<div v-if="e.comparison" class="emergency-baseline" data-testid="emergency-baseline"><b>Baseline · 维持当前状态（不可执行）</b><span>+30 水位 {{e.baseline?.final_water_level.toFixed(2)}} cm</span><span>规则风险 {{e.baseline?.final_risk_score.toFixed(1)}}</span><span>面积 {{e.baseline?.final_affected_area.toFixed(0)}} m²</span><small>基准 {{(e.comparison.baseline_simulation_time/60).toFixed(2)}} 仿真分钟 · {{e.comparison.compare_latency_ms.toFixed(0)}} ms · {{e.comparison.baseline_state_hash.slice(0,12)}}</small></div>
<p v-if="e.selectedPlan">空间预览：蓝色轮廓表示拟启动泵，黄色入口标记表示拟封控；仅预览，不改变实时状态。</p><div class="emergency-cards"><article v-for="p in e.availablePlans" :key="p.plan_code" :data-plan="p.plan_code" :data-available="p.available" :class="{selected:p.plan_code===e.selectedPlan}"><h4>{{p.name}}</h4><p>{{p.description}}</p><ul><li v-for="(a,i) in p.actions" :key="i">{{a.target_id}} · {{a.action_type}} <small>+{{a.delay_seconds}} s</small></li></ul><p v-if="!p.available" class="emergency-stale">{{p.unavailable_reasons.join('；')}}</p><dl v-if="result(p.plan_code)"><div><dt>+30 水位 / 较 Baseline 降低</dt><dd>{{result(p.plan_code)!.final_water_level.toFixed(2)}} cm / {{result(p.plan_code)!.water_reduction?.toFixed(2)}} cm</dd></div><div><dt>+30 规则风险 / 降幅</dt><dd>{{result(p.plan_code)!.final_risk_score.toFixed(1)}} / {{result(p.plan_code)!.risk_reduction?.toFixed(1)}}</dd></div><div><dt>峰值水位 / 峰值风险</dt><dd>{{result(p.plan_code)!.peak_water_level.toFixed(2)}} cm / {{result(p.plan_code)!.peak_risk_score.toFixed(1)}}</dd></div><div><dt>影响面积</dt><dd>{{result(p.plan_code)!.final_affected_area.toFixed(0)}} m²</dd></div><div><dt>风险低于 60 / 40</dt><dd>{{response(result(p.plan_code)!.time_to_risk_below_60)}} / {{response(result(p.plan_code)!.time_to_risk_below_40)}}</dd></div><div><dt>资源消耗指数</dt><dd>{{result(p.plan_code)!.resource_cost_score.toFixed(2)}}</dd></div><div><dt>影响人员 / 现有车辆</dt><dd>{{result(p.plan_code)!.affected_people}} / {{result(p.plan_code)!.affected_vehicles}}</dd></div></dl><button :disabled="!p.available||e.loading" @click="e.select(p.plan_code)">{{e.selectedPlan===p.plan_code?'已选择 · 三维预览中':'选择并预览'}}</button></article></div>
<div v-if="e.comparison" class="emergency-charts"><article><h4>水位对比 · 同一基线，四个独立未来</h4><ChartCanvas :option="water" label="应急方案水位对比"/></article><article><h4>规则风险对比 · 非 XGBoost 因果预测</h4><ChartCanvas :option="risk" label="应急方案风险对比"/></article></div>
<p v-if="e.comparison" class="emergency-notes">{{e.comparison.cost_definition}} {{e.comparison.response_definition}}</p><div class="emergency-actions"><button class="flood-primary" data-testid="emergency-execute" :disabled="!selected?.available||!e.comparison||!result(e.selectedPlan)||stale||e.loading||rt.connectionStatus!=='connected'" @click="execute">确认仿真执行 {{e.selectedPlan}}</button><button v-if="e.execution&&['pending','executing'].includes(e.execution.status)" @click="e.cancel" :disabled="e.loading">取消尚未执行步骤</button><span v-if="!rt.state?.running">仿真已暂停；执行请求将排队，点击“继续仿真”后动作开始。</span></div>
<div v-if="e.execution" class="emergency-execution" data-testid="emergency-execution" :data-status="e.execution.status" :data-phase="e.execution.phase"><h4>{{e.execution.plan_code}} · {{emergencyPhaseLabels[e.execution.phase]}} <small>操作人 {{e.execution.operator}}</small></h4><ul><li v-for="s in e.execution.steps" :key="s.index">{{s.status}} · {{s.message}}</li></ul><p v-if="e.execution.phase==='STABILIZING'">{{(rt.state?.flood?.riskScore??100)<40?'风险已降至一般水平。':'风险开始回落，继续监测。'}} 内涝告警保留，可前往事件复盘完成工单并人工关闭。</p></div>
<ol class="emergency-timeline" data-testid="emergency-timeline"><li v-for="(event,i) in e.events" :key="i"><time>{{new Date(event.timestamp).toLocaleTimeString()}} / {{((event.simulation_time??0)/60).toFixed(2)}} min</time> {{event.message}}</li></ol></section></template>
